/**
 * Compile test: each golden dotnet file is dropped into fixtures/compile/dotnet
 * (pinned to LaunchDarkly.ServerSdk 8.x) with a consumer that calls every
 * generated member, then built with every warning an error and every analyzer
 * on (DESIGN.md → Generated code by target → dotnet):
 *
 * - `modern` (net8.0, latest C#, nullable enabled) and `legacy`
 *   (netstandard2.0, C# 7.3) build the file as generated;
 * - `modern` builds it again without the `<auto-generated/>` line, so the
 *   analyzers that skip generated code run on it too;
 * - `dotnet format --verify-no-changes --include-generated` changes nothing.
 *
 * The consumer reads deprecated members inside `#pragma warning disable
 * LDFLAG001, CS0618`. Without it, each one is an error: LDFLAG001 with the
 * flag's UI link on `modern`, CS0618 on `legacy` (ADR 0003). The generated
 * file's deprecated members reference each other without a warning.
 *
 * Needs the .NET 8 SDK on the PATH. Run with `pnpm test:compile -t dotnet`.
 */
import { execFile } from 'node:child_process';
import { readdir, readFile, writeFile } from 'node:fs/promises';
import { join, resolve } from 'node:path';
import { promisify } from 'node:util';
import { beforeAll, describe, expect, it } from 'vitest';
import { modelFlag } from '../../core/test/builders.js';
import { dotnetEmitter } from '../src/index.js';
import { IDENTIFIER } from '../src/identifier.js';

const REPO_ROOT = resolve(import.meta.dirname, '../../..');
const GOLDEN_DIR = join(REPO_ROOT, 'fixtures/golden/dotnet');
const FIXTURE_DIR = join(REPO_ROOT, 'fixtures/compile/dotnet');
const MODERN = join(FIXTURE_DIR, 'modern/Modern.csproj');
const LEGACY = join(FIXTURE_DIR, 'legacy/Legacy.csproj');

const goldens = (await readdir(GOLDEN_DIR)).filter((f) => f.endsWith('.cs')).sort();

/** A fallback value of each generated C# type, for the consumer's calls. */
const FALLBACKS: Record<string, string> = {
  bool: 'false',
  string: '"fallback"',
  int: '1',
  double: '1.5',
  LdValue: 'LdValue.Null',
};

/** A member is deprecated when its signature follows the `#if` / `#else` / `#endif` `[Obsolete]` pair. */
const OBSOLETE = '(#endif\\n)?';

/**
 * C# that calls every flag method, `Detail` method and `FlagKeys` constant in
 * `generated`, read back from its signatures. The deprecated ones are read
 * inside `#pragma warning disable LDFLAG001, CS0618`, unless `suppress` is false.
 */
function consumerFor(generated: string, { suppress = true } = {}): string {
  const namespace = /^namespace (\S+)$/m.exec(generated)?.[1];
  const methods = [
    ...generated.matchAll(
      new RegExp(`^${OBSOLETE} {8}public (\\S+) (${IDENTIFIER})\\(Context context, (\\w+) fallback\\)$`, 'gmu'),
    ),
  ];
  const keys = [...generated.matchAll(new RegExp(`^${OBSOLETE} {8}public const string (${IDENTIFIER}) = `, 'gmu'))];
  if (!namespace || methods.length === 0 || methods.length !== keys.length * 2) {
    throw new Error('cannot read the generated members back');
  }
  const locals = [
    ...methods.map(([, obsolete, type, name, fallbackType], i) => ({
      deprecated: obsolete !== undefined,
      declaration: `${type} v${i} = flags.${name}(context, ${FALLBACKS[fallbackType!]!});`,
      use: type!.startsWith('EvaluationDetail<') ? `v${i}.Value` : `v${i}`,
    })),
    ...keys.map(([, obsolete, name], i) => ({
      deprecated: obsolete !== undefined,
      declaration: `string k${i} = FlagKeys.${name};`,
      use: `k${i}`,
    })),
  ];
  const current = locals.filter((l) => !l.deprecated).map((l) => l.declaration);
  const deprecated = locals.filter((l) => l.deprecated).map((l) => l.declaration);
  const statements =
    suppress && deprecated.length > 0
      ? [
          ...current,
          '#pragma warning disable LDFLAG001, CS0618 // calls a deprecated flag on purpose',
          ...deprecated,
          '#pragma warning restore LDFLAG001, CS0618',
        ]
      : [...current, ...deprecated];
  const uses = locals.map((l) => l.use);
  return `namespace Consumer
{
    using LaunchDarkly.Sdk;
    using LaunchDarkly.Sdk.Server.Interfaces;
    using ${namespace};

    /// <summary>Calls every generated member.</summary>
    public static class Calls
    {
        /// <summary>Calls every generated member.</summary>
        /// <param name="client">The client.</param>
        /// <returns>A summary string.</returns>
        public static string Run(ILdClient client)
        {
            var flags = new Flags(client);
            var context = Context.New("user-key");
${statements.map((s) => (s.startsWith('#') ? `${s}\n` : `            ${s}\n`)).join('')}            return string.Join(",", ${uses.join(', ')});
        }
    }
}
`;
}

const run = async (args: string[]): Promise<{ ok: boolean; output: string }> =>
  promisify(execFile)('dotnet', args, { cwd: FIXTURE_DIR, maxBuffer: 16 * 1024 * 1024 }).then(
    ({ stdout }) => ({ ok: true, output: stdout }),
    (err: { stdout?: string; stderr?: string }) => ({ ok: false, output: `${err.stdout ?? ''}${err.stderr ?? ''}` }),
  );

/** `dotnet build` with no restore; `ok` with its output on failure, for the assertion message. */
async function build(project: string, ...props: string[]): Promise<string> {
  const result = await run(['build', project, '--no-restore', '-nologo', '-v:q', '-clp:NoSummary', ...props]);
  return result.ok ? 'ok' : result.output;
}

/** Builds `generated` and its consumer on both projects, with and without `<auto-generated/>`, and checks `dotnet format`. */
async function expectCompiles(generated: string): Promise<void> {
  expect(generated).toContain('\n// <auto-generated/>\n');
  await writeFile(join(FIXTURE_DIR, 'Flags.g.cs'), generated);
  await writeFile(join(FIXTURE_DIR, 'Flags.cs'), generated.replace('\n// <auto-generated/>\n', '\n'));
  await writeFile(join(FIXTURE_DIR, 'Consumer.cs'), consumerFor(generated));

  expect(await build(MODERN), 'modern').toBe('ok');
  expect(await build(LEGACY), 'legacy').toBe('ok');
  expect(await build(MODERN, '-p:FlagsFile=Flags.cs'), 'modern without <auto-generated/>').toBe('ok');

  const format = await run(['format', MODERN, '--verify-no-changes', '--include-generated', '--no-restore']);
  expect(format.output, 'dotnet format').toBe('');
  expect(format.ok).toBe(true);
}

describe('dotnet output compiles against LaunchDarkly.ServerSdk 8.x', () => {
  beforeAll(async () => {
    for (const project of [MODERN, LEGACY]) {
      const result = await run(['restore', project, '-nologo', '-v:q']);
      if (!result.ok) throw new Error(`dotnet restore ${project} failed:\n${result.output}`);
    }
  }, 300_000);

  it.each(goldens)('%s', async (file) => {
    await expectCompiles(await readFile(join(GOLDEN_DIR, file), 'utf8'));
  });

  // Emitted here rather than from a snapshot, since every target runs every snapshot.
  it('a Unicode alias and new-lines or control characters in single-line text', async () => {
    const [file] = dotnetEmitter.emit(
      {
        projectKey: 'my-project',
        flags: [
          modelFlag('cart-limits', {
            name: 'Cart\nlimits\u2028v2',
            description: 'One\u2029two\r\rThree\u0085four',
            kind: 'number',
            numberType: 'int',
            deprecated: true,
            deprecationMessage: 'Use "cart-v2" {now}.\nSee C:\\wiki\t<here>\r\u0085\u2028\u2029\u0007done',
          }),
          modelFlag('japan', { name: '日本', kind: 'string', aliases: { dotnet: '日本' } }),
          modelFlag('size', { kind: 'json', aliases: { dotnet: 'Größe' } }),
        ],
      },
      { id: 'dotnet', out: 'Flags.g.cs', sdkMajor: 8, options: { namespace: 'Ünïcode.Flägs' } },
      { generatorVersion: '0.0.0' },
    );
    const generated = file!.contents;
    expect(generated).toContain('public string 日本(Context context, string fallback)');
    await expectCompiles(generated);
  });

  const deprecating = goldens.filter((file) => file === 'doc-comments.g.cs');

  it.each(deprecating)('%s: calling a deprecated flag unsuppressed is LDFLAG001 on net5+ and CS0618 before', async (file) => {
    const generated = await readFile(join(GOLDEN_DIR, file), 'utf8');
    expect(generated).toContain('[System.Obsolete(');
    await writeFile(join(FIXTURE_DIR, 'Flags.g.cs'), generated);
    await writeFile(join(FIXTURE_DIR, 'Consumer.cs'), consumerFor(generated, { suppress: false }));

    const modern = await build(MODERN);
    expect(modern).toMatch(/Consumer\.cs.*error LDFLAG001: .* is obsolete: .* \(https:\/\/\S+\/flags\/[\w.-]+\)/);
    expect(modern).not.toContain('CS0618');
    expect(modern, 'the generated file itself raises nothing').not.toMatch(/Flags\.g\.cs.*(?:error|warning)/);

    const legacy = await build(LEGACY);
    expect(legacy).toMatch(/Consumer\.cs.*error CS0618/);
    expect(legacy).not.toContain('LDFLAG001');
    expect(legacy, 'the generated file itself raises nothing').not.toMatch(/Flags\.g\.cs.*(?:error|warning)/);
  });
});
